    size_t dot_pos = P_str.find('.');
    if (dot_pos == string::npos) {
        P_int = stoi(P_str) * 10000;
    } else {
        string int_part = P_str.substr(0, dot_pos);
        string frac_part = P_str.substr(dot_pos + 1);
        while (frac_part.size() < 4) frac_part += '0';
        if (frac_part.size() > 4) frac_part = frac_part.substr(0, 4);
        P_int = stoi(int_part) * 10000 + stoi(frac_part);
    }

    // If P is 0, no maps need to be studied
    if (P_int == 0) {
        cout << 0 << "\n";
        return 0;
    }

    // Total number of ways to choose 3 maps from N
    long long total = 1LL * N * (N - 1) * (N - 2) / 6;
    long long target = 1LL * P_int * total;

    // Binary search for minimum K
    int low = 1, high = N, ans = N;
    while (low <= high) {
        int mid = (low + high) / 2;
        int K = mid;
        int M = N - K;

        // Calculate favorable combinations
        // C(K,3) + C(K,2)*M + C(K,1)*C(M,2)/2
        long long favorable = 0;

        // C(K,3)
        if (K >= 3) {
            favorable += 1LL * K * (K - 1) * (K - 2) / 6;
        }

        // C(K,2) * M
        if (K >= 2) {
            favorable += 1LL * K * (K - 1) / 2 * M;
        }

        // C(K,1) * C(M,2) / 2
        if (K >= 1 && M >= 2) {
            favorable += 1LL * K * M * (M - 1) / 4;
        }

        // Check if favorable * 10000 >= target
        if (favorable * 10000LL >= target) {
            ans = K;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }

    cout << ans << "\n";
    return 0;
}
