    int N;
    double P;
    if(!(cin >> N >> P)) return 0;

    if (P <= 0.0) {
        cout << 0 << "\n";
        return 0;
    }

    const double EPS = 1e-9;

    // Try all possible values of s from 1 to N-1
    for (int s = 1; s <= N - 1; ++s) {
        int U = N - s;
        if (U < 2) {
            // If U=1, probability is 1.0
            if (1.0 >= P - EPS) {
                cout << s << "\n";
                return 0;
            }
            continue;
        }

        // Compute combinations
        double total = N * (N - 1) * (N - 2) / 6.0;

        double u = U * (U - 1) * (U - 2) / 6.0;  // C(U, 3)
        double v = s * U * (U - 1) / 2.0;        // s * C(U, 2)
        double w = (s * (s - 1) / 2.0) * U;      // C(s, 2) * U
        double x = s * (s - 1) * (s - 2) / 6.0;  // C(s, 3)

        double p_all_0 = u / total;
        double p_one_1 = v / total;
        double p_two_1 = w / total;
        double p_all_1 = x / total;

        double prob = 0.0;
        prob += (2.0 / 3.0) * p_one_1;
        prob += (1.0 / 3.0) * p_two_1;
        prob += 1.0 * p_all_1;

        if (prob >= P - EPS) {
            cout << s << "\n";
            return 0;
        }
    }

    // If not found, answer is N-1 (probability is 1.0)
    cout << N - 1 << "\n";
    return 0;
}
