#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    string P_str;
    if (!(cin >> N >> P_str)) return 0;

    // Parse P with up to 4 decimal digits
    int P_int = 0;
    size_t pos = P_str.find('.');
    if (pos == string::npos) {
        P_int = stoi(P_str) * 10000;
    } else {
        string int_part = P_str.substr(0, pos);
        string frac_part = P_str.substr(pos + 1);
        while (frac_part.size() < 4) frac_part += '0';
        if (frac_part.size() > 4) frac_part = frac_part.substr(0, 4);
        P_int = stoi(int_part) * 10000 + stoi(frac_part);
    }

    // We need to find minimum k (0 <= k <= N) such that probability >= P
    // Probability formula: 
    // For k studied maps out of N total maps
    // System picks 3 random maps from N.
    // Johnny discards one unstudied map if possible, otherwise random.
    // Opponent discards randomly among 3.
    // Game system picks randomly from remaining maps not discarded by either.

    // Let's derive the probability that the final map is studied.
    // Total ways to choose 3 maps: C(N,3)
    // For a given set of 3 maps with s studied maps (s = 0,1,2,3):
    // Johnny's strategy: discard an unstudied map if s < 3, else random studied map.
    // Opponent picks uniformly random among 3.
    // Final map is chosen uniformly from maps not discarded by either.

    // Case s = 0: all 3 unstudied. Johnny discards one unstudied, opponent discards one unstudied.
    // Remaining 1 map is unstudied. Prob studied = 0.

    // Case s = 1: 1 studied (A), 2 unstudied (B,C).
    // Johnny discards one unstudied (say B).
    // Opponent picks random among {A,B,C}:
    // - Picks A (prob 1/3): remaining maps {C} (unstudied) -> prob 0
    // - Picks B (prob 1/3): remaining maps {A,C}, system picks random -> prob 1/2 (A is studied)
    // - Picks C (prob 1/3): remaining maps {A} (studied) -> prob 1
    // Total prob = 1/3 * 0 + 1/3 * 1/2 + 1/3 * 1 = 1/6 + 1/3 = 1/2.

    // Case s = 2: 2 studied (A,B), 1 unstudied (C).
    // Johnny discards C (unstudied).
    // Opponent picks random among {A,B,C}:
    // - Picks A (1/3): remaining {B} (studied) -> prob 1
    // - Picks B (1/3): remaining {A} (studied) -> prob 1
    // - Picks C (1/3): remaining {A,B} (both studied) -> prob 1
    // Total prob = 1.

    // Case s = 3: all 3 studied.
    // Johnny discards random studied map.
    // Opponent picks random among 3 studied.
    // All remaining maps are studied. Prob = 1.

    // So overall probability = 
    // [C(k,1)*C(N-k,2) * 1/2 + C(k,2)*C(N-k,1) * 1 + C(k,3) * 1] / C(N,3)

    // Note: C(a,b) = 0 if a < b.

    // We need minimum k such that prob >= P_int/10000.

    auto C3 = [](long long n) -> long long {
        if (n < 3) return 0;
        return n * (n-1) * (n-2) / 6;
    };
    auto C2 = [](long long n) -> long long {
        if (n < 2) return 0;
        return n * (n-1) / 2;
    };
    auto C1 = [](long long n) -> long long {
        if (n < 1) return 0;
        return n;
    };

    long long total = C3(N);

    for (int k = 0; k <= N; ++k) {
        long long num = 0;
        // s=1: C(k,1)*C(N-k,2) * 1/2
        long long term1 = C1(k) * C2(N-k);
        // We'll multiply by 1/2 later to avoid fractions
        // s=2: C(k,2)*C(N-k,1) * 1
        long long term2 = C2(k) * C1(N-k);
        // s=3: C(k,3) * 1
        long long term3 = C3(k);

        // prob = (term1/2 + term2 + term3) / total
        // Compare: term1/2 + term2 + term3 >= P_int/10000 * total
        // Multiply by 2: term1 + 2*term2 + 2*term3 >= 2 * P_int/10000 * total
        // Use integer arithmetic: compare (term1 + 2*term2 + 2*term3) * 10000 >= 2 * P_int * total

        long long lhs = (term1 + 2*term2 + 2*term3) * 10000LL;
        long long rhs = 2LL * P_int * total;

        if (lhs >= rhs) {
            cout << k << "\n";
            return 0;
        }
    }

    cout << N << "\n";
    return 0;
}
